esqlQuery.esql:
FROM metrics-gcp.cloudstorage.otel-default
// Scope to Cloud Storage; this data stream carries every GCP service the receiver collects.
| WHERE resource.attributes.gcp.resource_type == "gcs_bucket"
    AND `metrics.storage.googleapis.com/storage/total_bytes` IS NOT NULL
//
// --- Snapshot handling -------------------------------------------------------------------------
// total_bytes is a point-in-time snapshot recomputed by Cloud Monitoring roughly once per day and
// re-reported on every poll. It must NEVER be summed over time: that would multiply it by the poll
// count. The correct shape is MAX per series within a narrow slice, then SUM across series.
// A bucket can hold several storage classes at once (lifecycle transitions, Autoclass), so the
// first STATS groups by bucket AND class and the second sums the classes together.
// The 2-day head and tail slices are wide enough to always contain at least one daily snapshot.
| STATS latest_class_bytes   = MAX(`metrics.storage.googleapis.com/storage/total_bytes`) WHERE @timestamp >= NOW() - 2 days,
        earliest_class_bytes = MAX(`metrics.storage.googleapis.com/storage/total_bytes`) WHERE @timestamp < NOW() - 12 days
    BY resource.attributes.bucket_name, attributes.storage_class
| STATS latest_bytes     = SUM(latest_class_bytes),
        earliest_bytes   = SUM(earliest_class_bytes),
        // Everything that is not an archival class is billed at a hot rate. Written as an exclusion
        // so that an unfamiliar class is counted as hot rather than silently ignored.
        latest_hot_bytes = SUM(latest_class_bytes) WHERE attributes.storage_class NOT IN ("NEARLINE", "COLDLINE", "ARCHIVE"),
        storage_classes  = VALUES(attributes.storage_class)
    BY resource.attributes.bucket_name
// Guard against divide-by-zero, and ignore buckets too small for growth to cost anything.
// 10 GiB; raise this so only buckets that matter to the bill can alert.
| WHERE earliest_bytes > 0 AND latest_bytes >= 10737418240
| EVAL growth_gib = ROUND((latest_bytes - earliest_bytes) / 1073741824.0, 2),
       growth_pct = ROUND((latest_bytes - earliest_bytes) / earliest_bytes * 100.0, 2),
       latest_gib = ROUND(latest_bytes / 1073741824.0, 2),
       hot_bytes_pct = ROUND(COALESCE(latest_hot_bytes, 0.0) / latest_bytes * 100.0, 1)
// 50% over 14 days is roughly a doubling per month. Lower to 25 for tighter budget control, or
// raise it for buckets that are expected to grow quickly.
| WHERE growth_pct > 50.0
| SORT growth_pct DESC
| LIMIT 50
